// ─── Seed Runner ───────────────────────────────────────────────────────────────
async function seedExamQanda() {
  try {
    await ExamQanda.deleteMany({ courseType: 'CE' });
    console.log('✓ Cleared existing CE exam Q&A records');

    const inserted = await ExamQanda.insertMany(examData);
    console.log(`✓ Inserted ${inserted.length} CE exam Q&A records`);

    // Summary by course
    const summary = examData.reduce((acc, q) => {
      const key = `${q.courseGroup.padEnd(10)} | ${q.part || 'N/A      '} | ${q.examName} — ${q.version}`;
      acc[key] = (acc[key] || 0) + 1;
      return acc;
    }, {});

    console.log('\n── Insert Summary ──────────────────────────────────────────────');
    Object.entries(summary).forEach(([key, count]) => {
      console.log(`  ${String(count).padStart(2)} Qs  →  ${key}`);
    });
    console.log('────────────────────────────────────────────────────────────────');
    console.log(`  TOTAL: ${inserted.length} questions`);

  } catch (err) {
    console.error('✗ Seed failed:', err);
  } finally {
    process.exit(0);
  }
}

seedExamQanda();